  ],
  "tradeOffs": [
    {
      "choice": "Cut text into subword pieces instead of characters or whole words",
      "gains": "Frequent words take a single token, rare words are spelled from pieces the vocabulary already has, and no text is unknown.",
      "costs": "A word's token count depends on how common its pieces were in the training text, so counts vary by word, case and language.",
      "sourceChunkIds": [
        "source-1#chunk-1",
        "source-1#chunk-2"
      ],
      "angle": "serves"
    },
    {
