      "gains": "More text fits in each token, so sequences are shorter.",
      "costs": "Every entry needs its own row in the embedding table, and rare entries are seen too seldom during training to be learned well.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ],
      "angle": "serves"
