  "failureModes": [
    {
      "kind": "edge_case",
      "description": "A prompt budgeted from word counts overflows the context window or the cost estimate, because the word-to-token link is loose and varies by language and by content: a language rare in training text needed about 3 times as many tokens for the same meaning.",
